package com.bettertoppi.topuhud.modmenu;
import com.bettertoppi.topuhud.config.ConfigManager;import com.bettertoppi.topuhud.config.TopuHudConfig;import com.bettertoppi.topuhud.hud.HudManager;import net.minecraft.client.MinecraftClient;import net.minecraft.client.gui.DrawContext;import net.minecraft.client.gui.screen.Screen;import net.minecraft.client.gui.widget.ButtonWidget;import net.minecraft.text.Text;
public final class TopuScreenEditor extends Screen{private final Screen parent;private final TopuHudConfig config;private HudManager.HudId dragging;private int ox,oy;public TopuScreenEditor(Screen p){super(Text.literal("Topu HUD Editor"));parent=p;config=ConfigManager.get();}@Override protected void init(){addDrawableChild(ButtonWidget.builder(Text.literal("Done"),b->closeEditor()).dimensions(width/2-50,height-30,100,20).build());}private void closeEditor(){dragging=null;ConfigManager.save();MinecraftClient.getInstance().setScreen(parent);}@Override public void close(){closeEditor();}@Override public boolean mouseClicked(double x,double y,int button){if(super.mouseClicked(x,y,button))return true;if(button!=0)return false;HudManager.HudId[] ids=HudManager.HudId.values();for(int i=ids.length-1;i>=0;i--){HudManager.HudId id=ids[i];if(!HudManager.isEnabledForEditor(id))continue;int[] p=HudManager.getPositionForEditor(config,id);int w=HudManager.getWidthForEditor(id),h=HudManager.getHeightForEditor(id);if(x>=p[0]&&x<=p[0]+w&&y>=p[1]&&y<=p[1]+h){dragging=id;ox=(int)x-p[0];oy=(int)y-p[1];return true;}}return false;}@Override public boolean mouseDragged(double x,double y,int button,double dx,double dy){if(button!=0||dragging==null)return super.mouseDragged(x,y,button,dx,dy);int w=HudManager.getWidthForEditor(dragging),h=HudManager.getHeightForEditor(dragging);HudManager.setPositionForEditor(config,dragging,Math.max(0,Math.min(width-w,(int)x-ox)),Math.max(28,Math.min(height-30-h,(int)y-oy)));return true;}@Override public boolean mouseReleased(double x,double y,int button){if(button==0&&dragging!=null){dragging=null;ConfigManager.save();return true;}return super.mouseReleased(x,y,button);}@Override public void render(DrawContext d,int mx,int my,float delta){d.fill(0,0,width,height,0xAA101010);d.drawText(textRenderer,Text.literal("TOPU HUD EDITOR"),10,9,0xFFFFFF,true);d.drawText(textRenderer,Text.literal("Drag HUD elements to move them"),10,38,0xAAAAAA,false);for(HudManager.HudId id:HudManager.HudId.values()){if(!HudManager.isEnabledForEditor(id))continue;int[] p=HudManager.getPositionForEditor(config,id);int w=HudManager.getWidthForEditor(id),h=HudManager.getHeightForEditor(id);boolean s=dragging==id;d.fill(p[0],p[1],p[0]+w,p[1]+h,s?0x6633AA77:0x55222222);d.drawText(textRenderer,Text.literal(id.name()),p[0]+4,p[1]+4,s?0x00FF88:0xFFFFFF,true);}super.render(d,mx,my,delta);}}
